    MotorLatch : BOOL;
END_VAR

MotorLatch := FALSE;

IF EStop = FALSE THEN
    MotorLatch := FALSE;
ELSIF Start AND NOT Stop THEN
    MotorLatch := TRUE;
ELSIF Stop THEN
    MotorLatch := FALSE;
END_IF;

Motor := MotorLatch AND EStop;
END_PROGRAM

