PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : constant INT := 10;
    HighLimit : constant INT := 90;
END_VAR

IF Level <= LowLimit THEN
    PumpIn := TRUE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpIn_timer : TON;
END_VAR

// Logic to maintain tank level within hysteresis
IF Level <= 10 THEN
    PumpIn := TRUE;
ELSIF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Safety condition: PumpIn cannot be on if Level is at or above the high limit
IF Level >= 90 AND PumpIn THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

