PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    A_timer : TON;
    B_timer : TON;
END_VAR

IF OpenA_Cmd AND NOT OpenB_Cmd THEN
    A_timer(IN := TRUE, PT := T#0s);
    B_timer(IN := FALSE, PT := T#0s);
    DoorA := A_timer.Q;
    DoorB := NOT A_timer.Q;
ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
    A_timer(IN := FALSE, PT := T#0s);
    B_timer(IN := TRUE, PT := T#0s);
    DoorA := NOT B_timer.Q;
    DoorB := B_timer.Q;
ELSE
    A_timer(IN := FALSE, PT := T#0s);
    B_timer(IN := FALSE, PT := T#0s);
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

