    NS_allred : TON;
    EW_green : TON;
    EW_yellow : TON;
    EW_allred : TON;
END_VAR

CASE State OF
    0: 
        NS_green(IN := TRUE, PT := T#2s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := FALSE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := TRUE, PT := T#1s);
        NS_G := NS_green.Q;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := EW_allred.Q;
    1: 
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := TRUE, PT := T#1s);
        NS_allred(IN := FALSE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := TRUE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := NS_yellow.Q;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := EW_allred.Q;
    2: 
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#1s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := NS_allred.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := FALSE;
    3: 
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#0s);
        EW_green(IN := TRUE, PT := T#2s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := NS_allred.Q;
        EW_G := EW_green.Q;
        EW_Y := FALSE;
        EW_R := FALSE;
    4: 
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := TRUE, PT := T#1s);
        EW_allred(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := NS_allred.Q;
        EW_G := FALSE;
        EW_Y := EW_yellow.Q;
        EW_R := FALSE;
    5: 
        NS_green(IN := FALSE, PT := T#0s);
        NS_yellow(IN := FALSE, PT := T#0s);
        NS_allred(IN := TRUE, PT := T#0s);
        EW_green(IN := FALSE, PT := T#0s);
        EW_yellow(IN := FALSE, PT := T#0s);
        EW_allred(IN := TRUE, PT := T#1s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := NS_allred.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := EW_allred.Q;
END_CASE

IF State >= 3 THEN
    State := State - 3;
END_IF;

IF State < 0 OR State > 5 THEN
    State := 0;
END_IF;

END_PROGRAM

PROGRAM intersection
VAR CONSTANT PT_GREEN : TIME := T#2s;
VAR CONSTANT PT_YELLOW : TIME := T#1s;
VAR CONSTANT PT_ALLRED : TIME := T#1s;
VAR State : INT;
VAR TNS : TON;
VAREW : TON;
VARALL : TON;
END_VAR

CASE State OF
    0:
        TNS(IN := TRUE, PT := PT_GREEN);
        TNS.Q => 
            NS_G := TRUE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
