            EW_R := FALSE;
    2:
        TALL(IN := TRUE, PT := PT_ALLRED);
        TALL.Q => 
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
        ELSE =>
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := FALSE;
    3:
        TEW(IN := TRUE, PT := PT_GREEN);
        TEW.Q => 
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := TRUE;
            EW_Y := FALSE;
            EW_R := FALSE;
        ELSE =>
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := FALSE;
    4:
        TEW(IN := TRUE, PT := PT_YELLOW);
        TEW.Q => 
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := TRUE;
            EW_R := FALSE;
        ELSE =>
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
