            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := TRUE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := TRUE;
        ELSE =>
            NS_G := FALSE;
            NS_Y := FALSE;
            NS_R := FALSE;
            EW_G := FALSE;
            EW_Y := FALSE;
            EW_R := FALSE;
END_CASE;

// Advance state on each tick
IF TNS.Q OR TALL.Q OR TEW.Q THEN
    State := State + 1;
    IF State > 5 THEN
        State := 0;
    END_IF;
END_IF;

END_PROGRAM

