PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND EStop AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;
    1: // Fill
        FillValve := TRUE;
        DrainValve := FALSE;
        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
    2: // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            State := 3;
        END_IF;
    3: // React
        Heater := TRUE;
        Agitator := TRUE;
        T1(IN := TRUE, PT := T#3s);
        IF T1.Q THEN
            State := 4;
        END_IF;
    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT;
END_VAR

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF NOT EStop AND StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0: -- Idle
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1;
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
        1: -- Fill
            IF Level >= LVL_HIGH THEN
                State := 2;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
        2: -- Heat
            IF Temp >= TEMP_SET THEN
                State := 3;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
            Heater := TRUE;
            Agitator := TRUE;
        3: -- React
            IF Ticks >= PT_REACT THEN
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
            Heater := TRUE;
            Agitator := TRUE;
        4: -- Drain
            IF Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
            DrainValve := TRUE;
        ELSE
            State := 0;
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_CASE;
    END_IF;
END_IF;

-- Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;
IF Heater OR Agitator AND Level < LIQ_MIN THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILL : INT := 1;
    HEAT : INT := 2;
    REACT : INT := 3;
    DRAIN : INT := 4;
END_VAR

IF NOT EStop THEN
    State := IDLE;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        IDLE:
            IF Level < LVL_HIGH THEN
                State := FILL;
            ELSE
                State := HEAT;
            END_IF;
        FILL:
            FillValve := TRUE;
            IF Level >= LVL_HIGH THEN
                State := HEAT;
            END_IF;
        HEAT:
            Heater := TRUE;
            Agitator := TRUE;
            IF Temp >= TEMP_SET THEN
                State := REACT;
            END_IF;
        REACT:
            Heater := TRUE;
            Agitator := TRUE;
            IF PT_REACT <= TON(T1).Q THEN
                State := DRAIN;
            END_IF;
        DRAIN:
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := IDLE;
            END_IF;
    END_CASE;
END_IF;

T1(IN := TRUE, PT := PT_REACT);
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT;
    FillTimer : TON;
END_VAR

CASE State OF
    0: -- Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: -- Fill
        IF NOT EStop AND Level >= LVL_HIGH AND LIQ_MIN <= Level THEN
            State := 2;
        ELSIF NOT EStop AND LIQ_MIN > Level THEN
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    2: -- Heat
        IF NOT EStop AND Temp >= TEMP_SET AND LIQ_MIN <= Level THEN
            State := 3;
        ELSIF NOT EStop AND LIQ_MIN <= Level THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    3: -- React
        IF NOT EStop AND LIQ_MIN <= Level THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

        IF FillTimer.Q THEN
            State := 4;
        ELSIF NOT EStop AND LIQ_MIN > Level THEN
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    4: -- Drain
        IF NOT EStop AND Level <= LVL_LOW AND LIQ_MIN <= Level THEN
            State := 0;
        ELSIF NOT EStop AND LIQ_MIN <= Level THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;
END_CASE

-- Safety conditions
IF FillValve AND DrainValve OR LIQ_MIN > Level THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF

IF NOT EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF

END_PROGRAM

