    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0; // Emergency Stop -> Idle
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1; // Start Batch -> Fill
    FillValve := TRUE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF State = 1 AND Level >= LVL_HIGH THEN
    State := 2; // Fill Complete -> Heat
    FillValve := FALSE;
    Heater := TRUE;
    Agitator := TRUE;
    DrainValve := FALSE;
ELSIF State = 2 AND Temp >= TEMP_SET THEN
    State := 3; // Heat Complete -> React
    FillValve := FALSE;
    Heater := TRUE;
    Agitator := TRUE;
    DrainValve := FALSE;
ELSIF State = 3 AND Level >= LIQ_MIN THEN
    IF NOT DrainValve OR Level < LVL_LOW THEN
        State := 4; // React Complete -> Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
    END_IF;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0; // Drain Complete -> Idle
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    T : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        ELSE
            FillValve := TRUE;
        END_IF;

    2: // Heat
        IF Temp >= TEMP_SET OR NOT EStop THEN
            State := 3;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    3: // React
        IF NOT EStop AND T.Q THEN
            State := 4;
        ELSE
            T(IN := TRUE, PT := PT_REACT);
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    4: // Drain
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        ELSE
            DrainValve := TRUE;
        END_IF;
END_CASE;

// Safety conditions
FillValve := (State <> 1) AND (NOT EStop);
DrainValve := (State <> 4) AND (NOT EStop);
Heater := (State = 2) AND (Level >= LIQ_MIN) AND (NOT EStop);
Agitator := (State = 2) AND (Level >= LIQ_MIN) AND (NOT EStop);

END_PROGRAM

