PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0: // Idle
            IF StartCycle AND Level < 90 THEN
                State := 1;
            END_IF;
        1: // Filling
            IF Level >= 90 THEN
                State := 2;
            END_IF;
        2: // Draining
            IF Level <= 10 THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

// Safety conditions
IF Pump AND Valve THEN
    State := 0;
END_IF;
IF Level >= 90 AND Pump THEN
    State := 0;
END_IF;
IF Level <= 10 AND Valve THEN
    State := 0;
END_IF;

END_PROGRAM

