            PurgeTimer(IN := TRUE, PT := T#3s);
        END_IF;

    1:
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF NOT PurgeTimer.Q THEN
            State := 2;
            IgnitionTimer(IN := TRUE, PT := T#2s);
        END_IF;

    2:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF Flame THEN
            State := 3;
        ELSIF NOT EStop OR StopPB THEN
            State := 0;
        END_IF;

    3:
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR NOT EStop OR StopPB THEN
            State := 0;
        END_IF;

    ELSE:
        State := 0;
END_CASE;

IF Not EStop OR StopPB THEN
    State := 0;
END_IF;

END_PROGRAM

