VAR
    State : INT := 0;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

T_C3(IN := NOT EStop AND StartPB AND State < 3, PT := T#2s);
T_C2(IN := NOT EStop AND T_C3.Q AND State < 2, PT := T#2s);

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF T_C3.Q THEN
            State := 1;
        END_IF;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF T_C2.Q THEN
            State := 2;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
