        IF StartPB AND NOT EStop THEN
            State := 1;
            T1(IN := TRUE, PT := T#2s);
        END_IF;
    1:
        IF T1.Q THEN
            State := 2;
            T2(IN := TRUE, PT := T#2s);
        END_IF;
    2:
        IF T2.Q THEN
            State := 3;
        END_IF;
    3:
        IF NOT StartPB OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

C1 := State >= 3;
C2 := State >= 2;
C3 := State >= 1;

