        C2 := FALSE;
        C3 := FALSE;
        T_C3(IN := FALSE);
        T_C2(IN := FALSE);
        IF StartPB AND NOT EStop THEN
            State := 1;
            T_C3(IN := TRUE, PT := T#2s);
        END_IF;

    1: // C3 only
        C1 := FALSE;
        C2 := FALSE;
        C3 := T_C3.Q;
        IF T_C3.Q AND NOT EStop THEN
            State := 2;
            T_C2(IN := TRUE, PT := T#2s);
        ELSIF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    2: // C3 + C2
        C1 := FALSE;
        C2 := T_C2.Q;
        C3 := T_C3.Q;
        IF T_C2.Q AND T_C3.Q AND NOT EStop THEN
            State := 3;
            C1 := TRUE;
        ELSIF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    3: // All three
        C1 := TRUE;
        C2 := T_C2.Q;
        C3 := T_C3.Q;
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
